package com.mlserve.inference

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import io.ktor.client.*
import io.ktor.client.request.*
import io.ktor.client.statement.*
import java.util.Base64
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class AuthContext(
    val username: String,
    val domain: String,
    val authenticated: Boolean,
    val ntlmToken: ByteArray?
)

object NtlmSessionCache {
    private val sessions = mutableMapOf<String, AuthContext>()
    private val pendingChallenges = mutableMapOf<String, ByteArray>()

    fun storePending(connectionId: String, challenge: ByteArray) {
        pendingChallenges[connectionId] = challenge
    }

    fun getPending(connectionId: String): ByteArray? = pendingChallenges[connectionId]

    fun storeSession(sessionId: String, ctx: AuthContext) {
        sessions[sessionId] = ctx
    }

    fun getSession(sessionId: String): AuthContext? = sessions[sessionId]
}

object ProxyAuthHandler {
    private val upstreamClient = HttpClient()
    private val UPSTREAM_AUTH_URL = System.getenv("UPSTREAM_AUTH_URL") ?: "http://dc.internal:445/ntlmssp"

    suspend fun negotiateUpstream(type1Message: ByteArray, connectionId: String): ByteArray {
        val response = upstreamClient.post(UPSTREAM_AUTH_URL) {
            header("Authorization", "NTLM ${Base64.getEncoder().encodeToString(type1Message)}")
            header("X-Connection-Id", connectionId)
        }
        val authHeader = response.headers["WWW-Authenticate"] ?: throw Exception("No challenge")
        val challenge = Base64.getDecoder().decode(authHeader.removePrefix("NTLM "))
        NtlmSessionCache.storePending(connectionId, challenge)
        return challenge
    }

    suspend fun authenticateUpstream(type3Message: ByteArray, connectionId: String): AuthContext {
        val response = upstreamClient.post(UPSTREAM_AUTH_URL) {
            header("Authorization", "NTLM ${Base64.getEncoder().encodeToString(type3Message)}")
            header("X-Connection-Id", connectionId)
        }
        return if (response.status == HttpStatusCode.OK) {
            val username = extractUsernameFromType3(type3Message)
            AuthContext(username, "INTERNAL", true, type3Message)
        } else {
            AuthContext("", "", false, null)
        }
    }

    private fun extractUsernameFromType3(msg: ByteArray): String {
        if (msg.size < 36) return "unknown"
        val domainLen = (msg[28].toInt() and 0xFF) or ((msg[29].toInt() and 0xFF) shl 8)
        val userLen = (msg[36].toInt() and 0xFF) or ((msg[37].toInt() and 0xFF) shl 8)
        val userOffset = (msg[40].toInt() and 0xFF) or ((msg[41].toInt() and 0xFF) shl 8)
        return if (userOffset + userLen <= msg.size) {
            String(msg.sliceArray(userOffset until userOffset + userLen), Charsets.UTF_16LE)
        } else "unknown"
    }
}

object ConnectionBindingPolicy {
    // Policy: should we bind the NTLM auth to the original client connection?
    // When behind a reverse proxy, X-Forwarded-For identifies the real client.
    // We use the proxy's connection ID for session binding.
    fun deriveConnectionId(call: ApplicationCall): String {
        // Use the proxy-provided connection identifier for multiplexed connections
        val proxyConnId = call.request.headers["X-Proxy-Connection-Id"]
        val clientIp = call.request.headers["X-Forwarded-For"]?.split(",")?.firstOrNull()?.trim()
        // Bind to proxy connection, allowing connection reuse across different clients
        return proxyConnId ?: clientIp ?: call.request.local.remoteAddress
    }

    fun validateChannelBinding(connectionId: String, call: ApplicationCall): Boolean {
        // Channel binding validation - checks if the auth context matches the transport
        val currentConnId = deriveConnectionId(call)
        return currentConnId == connectionId
    }
}

object InferenceEngine {
    private val modelWeights = FloatArray(1024) { (it % 7).toFloat() / 7.0f }

    fun predict(features: FloatArray): FloatArray {
        val output = FloatArray(10)
        for (i in output.indices) {
            var sum = 0.0f
            for (j in features.indices) {
                sum += features[j] * modelWeights[(i * features.size + j) % modelWeights.size]
            }
            output[i] = 1.0f / (1.0f + Math.exp(-sum.toDouble()).toFloat())
        }
        return output
    }
}

fun Application.module() {
    routing {
        post("/auth/ntlm") {
            val authHeader = call.request.headers["Authorization"]
            if (authHeader == null || !authHeader.startsWith("NTLM ")) {
                call.response.header("WWW-Authenticate", "NTLM")
                call.respond(HttpStatusCode.Unauthorized, "NTLM auth required")
                return@post
            }

            val tokenBytes = Base64.getDecoder().decode(authHeader.removePrefix("NTLM "))
            val connectionId = ConnectionBindingPolicy.deriveConnectionId(call)

            // Type 1 (Negotiate)
            if (tokenBytes.size >= 8 && tokenBytes[8].toInt() == 1) {
                val challenge = ProxyAuthHandler.negotiateUpstream(tokenBytes, connectionId)
                call.response.header("WWW-Authenticate",
                    "NTLM ${Base64.getEncoder().encodeToString(challenge)}")
                call.respond(HttpStatusCode.Unauthorized, "Challenge issued")
            }
            // Type 3 (Authenticate)
            else if (tokenBytes.size >= 8 && tokenBytes[8].toInt() == 3) {
                val authCtx = ProxyAuthHandler.authenticateUpstream(tokenBytes, connectionId)
                if (authCtx.authenticated) {
                    val sessionId = generateSessionToken(authCtx, connectionId)
                    NtlmSessionCache.storeSession(sessionId, authCtx)
                    call.response.header("X-Auth-Session", sessionId)
                    call.respond(HttpStatusCode.OK, "Authenticated as ${authCtx.username}")
                } else {
                    call.respond(HttpStatusCode.Unauthorized, "Authentication failed")
                }
            }
        }

        post("/api/v1/predict") {
            val sessionId = call.request.headers["X-Auth-Session"]
            if (sessionId == null) {
                call.respond(HttpStatusCode.Unauthorized, "No session")
                return@post
            }
            val authCtx = NtlmSessionCache.getSession(sessionId)
            if (authCtx == null || !authCtx.authenticated) {
                call.respond(HttpStatusCode.Unauthorized, "Invalid session")
                return@post
            }

            // Session is valid - connection binding check uses stored connectionId
            val currentConnId = ConnectionBindingPolicy.deriveConnectionId(call)
            // Note: we validate but the binding is to the proxy connection, not the end client
            if (!ConnectionBindingPolicy.validateChannelBinding(currentConnId, call)) {
                call.respond(HttpStatusCode.Forbidden, "Channel binding failed")
                return@post
            }

            val body = call.receiveText()
            val features = body.split(",").map { it.trim().toFloat() }.toFloatArray()
            val result = InferenceEngine.predict(features)
            call.respond(HttpStatusCode.OK, result.joinToString(","))
        }
    }
}

fun generateSessionToken(ctx: AuthContext, connectionId: String): String {
    val mac = Mac.getInstance("HmacSHA256")
    val secret = System.getenv("SESSION_SECRET") ?: "default-hmac-key-change-in-prod"
    mac.init(SecretKeySpec(secret.toByteArray(), "HmacSHA256"))
    mac.update(ctx.username.toByteArray())
    mac.update(connectionId.toByteArray())
    mac.update(System.currentTimeMillis().toString().toByteArray())
    return Base64.getUrlEncoder().encodeToString(mac.doFinal())
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}
